document.documentElement.classList.toggle('native-shell',new URLSearchParams(location.search).get('native')==='ios');
const voteSymbol=choice=>'<img class="vote-symbol" src="/'+(choice==='slay'?'gloss':'toss')+'-symbol.svg" alt="" aria-hidden="true">';
import {PHOTO_CONSENT, PHOTO_CONSENT_VERSION, photoFilename, matchPhotoFilename} from './photo-tools.mjs';
import {parseProductCSV} from './csv-import.mjs';
import {generateShareImage, nativeShareData, canShareImage, productShareUrl} from './share-card.mjs';
let sharePromptTimer,shareRequest=0,currentShare=null;
const $ = s => document.querySelector(s);
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories=['Polish','Gel','Extensions','Tools','Prep & finish','Nail care'];
const state={products:[],daily:{},user:null,queue:[],index:0,filter:'All products',search:'',sort:'new',busy:false,admin:null,voteCategory:''};
let toastTimer;
const percent=p=>p.total?Math.round(p.slays/p.total*100):null;
const result=p=>p.total?`${percent(p)}% Gloss`:'No votes yet';
const votes=p=>`${p.total} ${p.total===1?'vote':'votes'}`;
const product=id=>state.products.find(p=>p.id===id);
const photo=(p,cls='')=>p.image?`<img data-product-photo="${esc(p.id)}" class="${cls}" src="${esc(p.image)}" alt="${esc(p.brand+' '+p.name)}" loading="lazy" referrerpolicy="no-referrer">`:photoPlaceholder(p);

function verdictBadge(p){const key=p.verdict||'pending',labels={pending:'Awaiting verdict',nay:'× Toss',slay:'✳ Gloss',grail:'♛ Holy Grail'};return `<span data-verdict="${esc(p.id)}" class="verdict-badge verdict-${key}">${labels[key]}</span>`;}
function trendBadge(p){const t=p.trend||{direction:'pending'},labels={pending:'Not enough recent votes',up:'↗ Trending up',down:'↘ Trending down',steady:'→ Holding steady'};const info=t.change===null||t.change===undefined?'Needs 5 votes in each 24-hour window.':`${t.change>0?'+':''}${t.change} percentage points in Gloss share: latest 24 hours vs previous 24 hours.`;return `<span data-trend="${esc(p.id)}" class="trend trend-${t.direction}" title="${esc(info)}">${labels[t.direction]}</span>`;}
function scaleGuide(){return '<div class="rating-guide"><strong>The community scale</strong><span>× Toss · under 50%</span><span>✳ Gloss · 50–84%</span><span>♛ Holy Grail · 85%+</span><small>Gloss vote percentage · badges unlock at 10 votes. Trends compare the latest 24 hours with the previous 24 hours: 5+ votes in each window and a change of 5 percentage points for an arrow. Updates every minute while this page is open.</small></div>';}

const route=()=>location.hash.slice(1).split('?')[0]||'vote';
const lookups=new WeakMap();
function isAmazonLink(value){try{return /(^|\.)(amazon\.[a-z.]+|amzn\.to|a\.co)$/i.test(new URL(value).hostname);}catch{return false;}}
function purchaseLabel(value){try{const host=new URL(value).hostname;if(isAmazonLink(value))return 'View on Amazon';if(/(^|\.)tiktok\.com$/i.test(host))return 'View on TikTok Shop';return 'View product';}catch{return 'View product';}}
function updateDisclosure(){let note=$('#amazon-disclosure');const needed=state.products.some(p=>p.affiliate&&isAmazonLink(p.url));if(needed&&!note){note=document.createElement('p');note.id='amazon-disclosure';note.className='form-note';document.querySelector('footer').append(note);}if(note){note.hidden=!needed;note.textContent='As an Amazon Associate I earn from qualifying purchases.';}}
function mediaControls(){return `<div class="media-tools"><label>Details source <small>· optional, if different from purchase link</small><input data-details-source type="url" placeholder="Brand or shop product page"></label><button type="button" class="small" data-action="lookup-product">Get product details ↗</button><p class="form-note">Uses the link above, or your purchase link. Your purchase link is kept unchanged.</p><div class="lookup-results" aria-live="polite"></div><div class="upload-line"><label class="upload-button">Upload photo<input type="file" accept="image/jpeg,image/png,image/webp" data-photo-upload></label><span class="form-note">JPEG, PNG, or WebP · up to 15 MB</span></div><p class="media-status form-note" role="status"></p></div>`;}
function showPhoto(form){const target=form.querySelector('.photo-preview');const value=form.elements.image.value;if(target)target.innerHTML=value?`<img src="${esc(value)}" alt="Selected product photo"><span class="form-note">Selected photo · review before saving</span>`:'';}
async function mediaAction(button){const form=button.closest('form');if(!form||form.dataset.mediaBusy)return;const target=form.querySelector('.lookup-results'),status=form.querySelector('.media-status');
 if(button.dataset.action==='apply-product-details'){const details=lookups.get(form);if(!details)return;for(const key of ['name','brand','description'])if(!form.elements[key].value.trim()&&details[key])form.elements[key].value=details[key];const selected=form.querySelector('input[name="suggested-image"]:checked');if(selected)form.elements.image.value=details.images[Number(selected.value)]||form.elements.image.value;showPhoto(form);status.textContent='Details applied to empty fields. Your purchase link is unchanged. Review and save when ready.';return;}
 const value=form.querySelector('[data-details-source]').value.trim()||form.elements.url.value.trim();if(!value){status.textContent='Paste a purchase link or a details source first.';return;}
 form.dataset.mediaBusy='true';button.disabled=true;target.textContent='Looking for product details…';status.textContent='';
 try{const details=await api('/admin/lookup',{url:value});if(!form.isConnected)return;lookups.set(form,details);target.innerHTML=`<p class="form-note">${esc(details.message)}</p>${details.name?`<strong>${esc(details.name)}</strong>`:''}${details.brand?`<p class="form-note">${esc(details.brand)}</p>`:''}${details.images.length?`<fieldset class="suggested-photos"><legend>Choose a photo</legend>${details.images.map((image,i)=>`<label><input type="radio" name="suggested-image" value="${i}" ${i===0?'checked':''}><img src="${esc(image)}" alt="Suggested product photo ${i+1}"></label>`).join('')}</fieldset>`:''}${details.name||details.images.length?'<button type="button" class="small lime" data-action="apply-product-details">Use suggested details & photo</button>':''}`;}
 catch(e){target.textContent=e.message;}finally{delete form.dataset.mediaBusy;button.disabled=false;}
}
async function resizePhoto(file){
 if(file.size>15000000)throw new Error('Choose a photo up to 15 MB.');
 const allowed=['image/jpeg','image/png','image/webp'];
 if(!allowed.includes(file.type)&&!(file.type===''&&/\.(jpe?g|png|webp)$/i.test(file.name)))throw new Error('Choose a JPEG, PNG, or WebP photo. If this is an iPhone HEIC photo, export it as JPEG first.');
 // Embedded data URLs work in browsers that block temporary blob URLs.
 const source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The photo could not be read. Choose the file again.'));reader.onabort=()=>reject(new Error('Photo reading was interrupted. Choose the file again.'));reader.readAsDataURL(file);});
 const image=await new Promise((resolve,reject)=>{const img=new Image();const timer=setTimeout(()=>{img.onload=img.onerror=null;reject(new Error('The photo took too long to open. Try a smaller JPEG or PNG.'));},20000);img.onload=()=>{clearTimeout(timer);if(!img.naturalWidth||!img.naturalHeight){reject(new Error('The photo has no readable image data. Try exporting a new JPEG or PNG.'));return;}resolve(img);};img.onerror=()=>{clearTimeout(timer);reject(new Error('This photo could not be opened. Export or save a new copy as JPEG or PNG, then try again. Renaming its extension does not convert it.'));};img.src=source;});
 const scale=Math.min(1,1600/image.naturalWidth,1600/image.naturalHeight),canvas=document.createElement('canvas');
 canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
 const context=canvas.getContext('2d');if(!context)throw new Error('Photo processing is unavailable. Refresh the page and try again.');
 context.drawImage(image,0,0,canvas.width,canvas.height);
 const base64=canvas.toDataURL('image/webp',.85).split(',')[1];
 if(base64.length>2666668)throw new Error('This photo is still too large after resizing. Choose a smaller image.');
 return base64;
}
document.addEventListener('change',async event=>{const input=event.target,form=input.closest('form');if(!form)return;if(input.name==='image'){showPhoto(form);return;}if(!input.matches('[data-photo-upload]')||!input.files[0])return;const status=form.querySelector('.media-status');if(form.dataset.mediaBusy){input.value='';return;}form.dataset.mediaBusy='true';input.disabled=true;status.textContent='Preparing and uploading your photo…';try{const base64=await resizePhoto(input.files[0]);const response=await api('/admin/upload',{base64});if(!form.isConnected)return;form.elements.image.value=response.image;showPhoto(form);status.textContent='Photo uploaded. Save the product to use it.';}catch(e){status.textContent=e.message;}finally{delete form.dataset.mediaBusy;input.disabled=false;input.value='';}});
async function api(path,body){const response=await fetch('/api'+path,{credentials:'same-origin',...(body!==undefined?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let data;try{data=await response.json();}catch{throw new Error('The site is still being connected. Please try again shortly.');}if(!response.ok){const e=new Error(data.error||'Something went wrong. Please try again.');e.status=response.status;e.code=data.code;throw e;}return data;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function accountLabel(){return state.user?.id.startsWith('identity:')?'Your account':'@'+(state.user?.username||'');}
function updateAccount(){$('#account-button').textContent=state.user?accountLabel():'Sign in ↗';}
async function refresh(){const data=await api('/products');state.products=data.products;categories.splice(0,categories.length,...new Set(data.products.map(p=>p.category)));state.daily=data.daily;updateAccount();updateDisclosure();}
function resetQueue(){state.queue=state.products.filter(p=>!p.my_vote&&(!state.voteCategory||p.category===state.voteCategory)).map(p=>p.id);for(let i=state.queue.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[state.queue[i],state.queue[j]]=[state.queue[j],state.queue[i]];}state.index=0;}
function tile(p){return `<article class="product-tile"><div class="tile-photo">${p.image?`<button class="tile-image-button" data-detail="${esc(p.id)}" aria-label="View ${esc(p.name)}">${photo(p)}</button>`:photo(p)}${verdictBadge(p)}</div><div class="tile-copy"><div class="brand">${esc(p.brand)}</div><h3><button class="text-button" data-detail="${esc(p.id)}">${esc(p.name)}</button></h3><div class="tile-bottom"><span class="score">${esc(result(p))}</span><span>${votes(p)} ${p.my_vote?'· Voted ✓':''}</span></div>${trendBadge(p)}</div></article>`;}

function highlight(kind){const entry=state.daily[kind],p=entry&&product(entry.id);return `<article class="highlight ${kind}"><div class="highlight-label">${kind==='slay'?'Gloss':'Toss'} of the day</div><span class="highlight-icon" aria-hidden="true">${kind==='slay'?'✳':'↘'}</span>${p?`${photo(p)}<h3>${esc(p.name)}</h3><p>${Math.round((kind==='slay'?entry.slays:entry.total-entry.slays)/entry.total*100)}% ${kind==='slay'?'Gloss':'Toss'} · ${entry.total} votes yesterday</p><button class="text-button" data-detail="${esc(p.id)}">See the verdict ↗</button>`:`<h3>${kind==='slay'?'The crown is open.':'The jury is out.'}</h3><p>${kind==='slay'?'Your votes decide who gets it.':'A fair verdict takes more than one opinion.'}</p>`}</article>`;}
function voteCard(){const p=product(state.queue[state.index]);if(!p)return `<div class="empty"><h2>${state.voteCategory?'You’re caught up in '+esc(state.voteCategory)+'.':state.queue.length?'You’re all caught up.':'The floor is yours.'}</h2><p>${state.products.length?'You’ve reached the end of these products. Explore the results or revisit products you skipped.':'New products will appear here as they are added.'}</p>${state.index>0?'<button data-action="previous-product">← Previous product</button> ':''}<button data-action="restart" class="pink">Revisit skipped products ↻</button> <a href="#discover">Explore results →</a></div>`;return `<article class="vote-card" id="vote-card"><div class="card-top-actions">${watchButton(p)}${shareButton(p,true)}<button type="button" class="text-button" data-detail="${esc(p.id)}" aria-label="View details: ${esc(p.name)}" title="Product details"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/></svg></button></div><div class="product-stage" data-swipe-skip><span class="tag stage-tag">${esc(p.category)}</span><span class="stage-counter">${state.index+1} / ${state.queue.length}</span>${photo(p)}${verdictBadge(p)}</div><div class="vote-info"><div class="brand">${esc(p.brand)}</div><div class="product-title"><h2>${esc(p.name)}</h2></div>${trendBadge(p)}<p>Tried it? Tell us what you really think.</p>${p.my_vote?voteEditButtons(p):`<div class="vote-actions"><button data-vote="slay" data-id="${esc(p.id)}">${voteSymbol('slay')} Gloss</button><button data-vote="nay" data-id="${esc(p.id)}">${voteSymbol('nay')} Toss</button></div>`}<div class="skip-row"><span class="swipe-hint">← Swipe next · back →</span><button class="text-button" data-action="skip">Haven’t tried it? Skip →</button></div></div></article>`;}
function home(){return `<div class="focus-controls"><button class="small" data-action="focus-vote">${document.body.classList.contains('focus-vote')?'Exit focus view ×':'Focus view ⛶'}</button></div><section class="intro"><div><div class="eyebrow">Beauty meets honesty.</div><h1>Worth the <em>gloss?</em></h1></div><p>The nail community calls it.<br>One product. One vote. No paid opinions.</p></section>${voteCategoryControl()}<section class="vote-layout" aria-label="Vote and daily highlights"><div id="voting-surface">${voteCard()}</div><aside class="highlights"><div class="section-label"><h2>The daily verdict</h2><span class="today-date">${new Intl.DateTimeFormat('en',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date())} · UTC</span></div>${highlight('slay')}${highlight('nay')}<div class="honesty">Daily picks need 10+ votes from yesterday. Every product starts at zero. Every opinion counts once.</div></aside></section><div class="ticker"><span>✳ Real experience</span><span>✳ No paid placements</span><span>✳ Your honest verdict</span><span>✳ Always free to vote</span></div>`;}
function filtered(){let list=state.products.filter(p=>(state.filter==='All products'||p.category===state.filter)&&(`${p.name} ${p.brand} ${p.category}`).toLowerCase().includes(state.search.toLowerCase()));if(state.sort==='slay')list=list.filter(p=>p.total>=10).sort((a,b)=>percent(b)-percent(a)||b.total-a.total);if(state.sort==='nay')list=list.filter(p=>p.total>=10).sort((a,b)=>percent(a)-percent(b)||b.total-a.total);if(state.sort==='votes')list.sort((a,b)=>b.total-a.total);return list;}
function results(){const list=filtered();return list.length?`<div class="grid">${list.map(tile).join('')}</div>`:`<div class="empty"><h2>No products here yet.</h2><p>${['slay','nay'].includes(state.sort)?'Ranked products need at least 10 votes. Try “All products” to see new arrivals.':'Try another search, or suggest the product you’re looking for.'}</p><a class="text-button" href="#submit">Suggest a product ↗</a></div>`;}
function discover(){return `<div class="eyebrow">Before you add to cart</div><h1>Let’s check <em>the verdict.</em></h1><p class="muted">Find your next staple. Or dodge a disappointing restock.</p>${scaleGuide()}<div class="toolbar"><label class="sr-only" for="search">Search products or brands</label><input id="search" type="search" placeholder="Search a product or brand…" value="${esc(state.search)}"><label class="sr-only" for="sort">Sort products</label><select id="sort"><option value="new">All products</option><option value="slay">Highest Gloss · 10+ votes</option><option value="nay">Highest Toss · 10+ votes</option><option value="votes">Most voted</option></select></div><div class="pill-row" aria-label="Product categories">${['All products',...categories].map(c=>`<button data-category="${esc(c)}" class="${c===state.filter?'active':''}" aria-pressed="${c===state.filter}">${esc(c)}</button>`).join('')}</div><div id="search-results" aria-live="polite">${results()}</div>`;}
function fields(p={},enhance=false){return `<div class="form-grid"><label>Product name<input name="name" required maxlength="120" value="${esc(p.name)}" placeholder="e.g. Bubble Bath"></label><label>Brand<input name="brand" required maxlength="80" value="${esc(p.brand)}" placeholder="e.g. OPI"></label></div><label>Category<input name="category" required maxlength="40" value="${esc(p.category||'')}" placeholder="Choose or type a new category" list="category-options"></label>${enhance?'<button type="button" class="small" data-action="search-product">Search product on the web ↗</button><p class="form-note">Enter a product name or brand above. Search opens in a new tab so you can copy a listing’s link back here.</p>':''}<label>Purchase link <small>· optional, HTTPS</small><input name="url" type="url" maxlength="2000" placeholder="https://…" value="${esc(p.url)}"></label>${enhance?mediaControls():''}<label>Product photo <small>· image link, optional</small><input name="image" type="text" inputmode="url" maxlength="2000" placeholder="https://…" value="${esc(p.image)}"></label>${enhance?'<div class="photo-preview" aria-live="polite"></div>':''}<label>Description<textarea name="description" maxlength="1500" placeholder="What should the community know about this product?">${esc(p.description)}</textarea></label>`;}
function submission(){return `<div class="eyebrow">Put it to the community</div><h1>What’s on <em>your desk?</em></h1><p><a class="profile-link" href="#submit-photo/">Share a photo for an existing product →</a></p><div class="two-col"><div><p class="muted">A viral find, a salon staple, or something that deserves a second opinion. Let’s get it on the voting deck.</p><div class="panel"><h2>Good products can speak for themselves.</h2><p>We welcome suggestions from nail techs and brands. Every submission is reviewed before it goes live.</p><p class="footnote">Submitting a product doesn’t buy a score, a feature, or a positive verdict. All products follow the same voting rules.</p></div></div><div class="panel">${state.user?`<form id="submission-form"><h2>Suggest a product</h2><p class="form-note">Submitting from ${esc(accountLabel())}</p><label>I’m submitting as<select name="submitter_type"><option value="tech">A nail tech / community member</option><option value="brand">A brand / company representative</option></select></label>${communityProductFields()}${communityPhotoFields(false)}<p class="form-error" role="alert"></p><button class="pink wide" type="submit">Send for review ↗</button></form>`:`<h2>A quick sign-in first.</h2><p class="muted">Use your free account to send a suggestion for review.</p><button class="pink" data-action="signin">Sign in or sign up ↗</button>`}</div></div>`;}
function admin(){if(!state.user)return `<div class="empty"><h1>Your nail desk.</h1><p>Sign in to manage the site.</p><button class="pink" data-action="signin">Sign in</button></div>`;if(!state.user.is_admin)return `<div class="about"><h1>Admin access</h1><p class="muted">This area is for the site owner. Community members can suggest products on the submission page.</p><details class="panel"><summary>Set up the site owner</summary><p class="form-note">Use the private setup code saved in your Netlify settings. It works once.</p><form id="claim-form"><label>Setup code<input name="token" type="password" required autocomplete="off"></label><p class="form-error" role="alert"></p><button class="dark">Claim admin access</button></form></details></div>`;if(!state.admin)return '<div class="loading">Loading your product desk…</div>';return `<div class="intro"><div><div class="eyebrow">Your product desk</div><h1>Behind <em>the verdict.</em></h1></div><div class="actions"><button class="pink" data-action="add-product">Add a product +</button><button data-action="bulk-open">Bulk product desk</button><button data-action="sheet-open">Paste sheet / bulk edit</button><button data-action="users-open">Users &amp; password resets</button><button data-action="photo-desk">Photo desk / bulk upload</button></div></div><section class="panel"><h2>Submissions to review · ${state.admin.submissions.length}</h2>${state.admin.submissions.length?state.admin.submissions.map(s=>`<div class="admin-row"><div><strong>${esc(s.brand)} · ${esc(s.name)}</strong><p>From @${esc(s.username)} · ${s.submitter_type==='brand'?'Brand representative':'Community member'}</p><p>${esc(s.description)}</p>${s.submission_kind==='photo'?'<p><strong>Photo for an existing product · approval replaces its current photo</strong></p>':''}${s.photo_key?`<img class="submission-review-photo" src="/api/submission-photo/${esc(s.id)}" alt="Submitted photo for ${esc(s.name)}"><details><summary>Photo permission · ${esc(new Date(s.consent_at).toLocaleDateString())}</summary><p>${esc(s.consent_text)}</p><p>File: ${esc(s.original_filename)} · ${esc(s.consent_version)}</p></details>`:''}${s.url?`<a class="text-button" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">View product ↗</a>`:''}</div><div class="actions"><button data-review="approve" data-id="${esc(s.id)}" class="lime">Approve</button><button data-review="reject" data-id="${esc(s.id)}">Decline</button></div></div>`).join(''):'<p class="muted">You’re all caught up. New suggestions will appear here.</p>'}</section><section class="panel editor"><h2>Your products · ${state.admin.products.length}</h2>${state.admin.products.map(p=>`<div class="admin-row"><div><strong>${esc(p.brand)} · ${esc(p.name)}</strong><p>${esc(p.category)} · ${p.active?'Visible':'Hidden'}${p.affiliate?' · Affiliate link':''}</p></div><button data-edit="${esc(p.id)}">Edit product ↗</button></div>`).join('')}</section>`;}
function about(){return `<article class="about"><div class="eyebrow">A fairer product verdict</div><h1>Real opinions.<br><em>Clear rules.</em></h1><h2>Gloss means you’d recommend it.</h2><p>Toss means it didn’t earn your recommendation. Vote based on your own experience using the product. If you haven’t tried it, skip it.</p><h2>One account. One vote per product.</h2><p>Your vote is saved to your account, including when you return on another device. Repeated clicks won’t add votes. You can change your choice in My Votes; it replaces your existing vote rather than adding another. Please don’t create extra accounts to influence a score.</p><h2>What the numbers mean</h2><p>The Gloss percentage is Gloss votes divided by all votes. Every score shows how many people voted. A product with no votes has no score. All-time rankings require at least 10 votes.</p><h2>Badges and live trends</h2>${scaleGuide()}<p>A trend measures changing approval, not sales or vote volume. Holding steady means the change is smaller than 5 percentage points. Too few recent votes means no trend yet.</p><h2>The daily verdict</h2><p>Changed votes use the time of their latest change for daily picks and trends. Daily picks use yesterday’s votes, from midnight to midnight UTC, with a minimum of 10 votes per product. Gloss of the Day needs a majority Gloss; Toss of the Day needs a majority Toss. If nothing qualifies, we leave the spot open. These are community opinions, not product safety assessments.</p><h2>Brands and affiliate links</h2><p>Brand submissions are reviewed before publication. Purchase links marked “Affiliate link” may earn the site a commission. Links do not affect scores or rankings. We don’t sell favorable votes or featured placement.</p><h2>Your account</h2><p>Create an account with your email and password. Verify your email before voting. Your email is private, and password-reset links are sent by Netlify Identity. We store account details, votes, submissions, and session cookies. Sign-in and submission limits help reduce abuse. Don’t include personal contact details in product descriptions.</p></article>`;}
async function render(){const r=route();document.body.classList.toggle('vote-page',r==='vote');if(r!=='vote')document.body.classList.remove('focus-vote');document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+r?'page':'false'));$('#main').innerHTML= r.startsWith('submit-photo/')?photoSubmissionPage(r.slice(13)):r.startsWith('product/')?sharedProductPage(r.slice(8)):r==='watchlist'?watchlistPage():r==='profile'?profilePage():r==='my-votes'?myVotes():r==='discover'?discover():r==='submit'?submission():r==='admin'?admin():r==='about'?about():home();if(r==='discover')$('#sort').value=state.sort;if(r==='admin'&&state.user?.is_admin&&!state.admin){try{state.admin=await api('/admin/data');if(route()==='admin')$('#main').innerHTML=admin();}catch(e){$('#main').innerHTML=`<div class="empty"><p>${esc(e.message)}</p><button data-action="retry">Try again</button></div>`;}}}
function openModal(html){const dialog=$('#modal');dialog.innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">×</button>${html}`;if(!dialog.open)dialog.showModal();}
function auth(mode='choose'){return emailAuth(mode);}

function detail(id){const p=product(id);if(!p)return;openModal(`${watchButton(p)}${shareButton(p)}<div class="brand">${esc(p.brand)} · ${esc(p.category)}</div><h2 id="modal-title">${esc(p.name)}</h2><div class="rated-photo">${photo(p,'modal-photo')}${verdictBadge(p)}</div>${trendBadge(p)}<p>${esc(p.description)}</p><div class="modal-bottom"><strong>${result(p)}</strong><span class="muted">${votes(p)}</span></div>${p.total?`<progress class="result-bar" max="100" value="${percent(p)}" aria-label="${percent(p)} percent Gloss"></progress><p class="form-note">${p.slays} Gloss · ${p.total-p.slays} Toss${p.total<10?' · Early votes — rankings start at 10':''}</p>`:'<p class="form-note">Be the first to give this product an honest verdict.</p>'}${p.my_vote?`<p class="form-success">Your ${esc(p.my_vote==='slay'?'Gloss':'Toss')} vote is saved ✓</p>${voteEditButtons(p)}`:`<div class="vote-actions"><button data-vote="slay" data-id="${esc(p.id)}">${voteSymbol('slay')} Gloss</button><button data-vote="nay" data-id="${esc(p.id)}">${voteSymbol('nay')} Toss</button></div>`}${p.url?`<div class="modal-bottom"><a class="text-button" href="${esc(p.url)}" rel="noopener noreferrer${p.affiliate?' sponsored':''}" target="_blank">${esc(purchaseLabel(p.url))} ↗</a></div>${p.affiliate?`<p class="form-note">Affiliate link: we may earn a commission. Your vote stays independent.${isAmazonLink(p.url)?' As an Amazon Associate I earn from qualifying purchases.':''}</p>`:''}`:''}`);}
function editProduct(id){const p=id?state.admin.products.find(p=>p.id===id):{};openModal(`<h2 id="modal-title">${id?'Edit product':'Add a product'}</h2><form id="product-form"><input name="id" type="hidden" value="${esc(id||'')}">${id?`<label>Product ID<input readonly value="${esc(id)}"></label><label>Suggested photo filename<input readonly value="${esc(photoFilename(p))}"></label>`:''}${fields(p,true)}<label>Purchase link type<select name="affiliate"><option value="false">Standard product link</option><option value="true" ${p.affiliate?'selected':''}>Affiliate link (disclosed to visitors)</option></select></label><label>Visibility<select name="active"><option value="true">Visible for voting</option><option value="false" ${p.active===false?'selected':''}>Hidden</option></select></label><p class="form-note">Use photos you have permission to display. Editing keeps existing votes.</p><p class="form-error" role="alert"></p><button class="pink wide">Save product</button></form>`);}
async function castVote(id,choice){if(state.busy)return;if(matchMedia('(max-width:680px)').matches)document.body.classList.add('focus-vote');if(!state.user){auth('signup');return;}state.busy=true;const buttons=document.querySelectorAll('[data-vote]');buttons.forEach(b=>b.disabled=true);try{await api('/vote',{product_id:id,choice});if($('#modal').open)$('#modal').close();const card=$('#vote-card');if(card){card.classList.add('leaving');await new Promise(r=>setTimeout(r,180));}if(state.queue[state.index]===id)state.index++;await refresh();await render();state.lastVote={...product(id),my_vote:choice};showVoteSharePrompt(state.lastVote);}catch(e){toast(e.message);if(e.status===401){state.user=null;updateAccount();auth();}if(e.status===409){await refresh();resetQueue();await render();}}finally{state.busy=false;document.querySelectorAll('[data-vote]').forEach(b=>b.disabled=false);}}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.detail){detail(b.dataset.detail);return;}
 if(b.dataset.changeVote){await changeVote(b.dataset.id,b.dataset.changeVote);return;}
 if(b.dataset.vote){await castVote(b.dataset.id,b.dataset.vote);return;}
 if(b.dataset.auth){auth(b.dataset.auth);return;}
 if(b.dataset.edit){editProduct(b.dataset.edit);return;}
 if(b.dataset.category){state.filter=b.dataset.category;await render();return;}
 if(b.dataset.review){b.disabled=true;try{await api('/admin/review',{id:b.dataset.id,action:b.dataset.review});state.admin=null;await refresh();await render();toast(b.dataset.review==='approve'?'Submission approved.':'Submission declined.');}catch(err){toast(err.message);b.disabled=false;}return;}
 const action=b.dataset.action;
 if(action==='search-product'){const form=b.closest('form');const query=[form.elements.brand.value.trim(),form.elements.name.value.trim()].filter(Boolean).join(' ');if(!query){form.querySelector('.form-error').textContent='Enter a product name or brand first, then search.';form.elements.name.focus();return;}form.querySelector('.form-error').textContent='';window.open('https://www.google.com/search?q='+encodeURIComponent(query),'_blank','noopener,noreferrer');return;}
 if(['lookup-product','apply-product-details'].includes(action)){await mediaAction(b);return;}
 if(action==='close')$('#modal').close();
 if(action==='signin')auth();
 if(action==='skip')skipProduct();if(action==='previous-product')previousProduct();
 if(action==='restart'){resetQueue();await render();}
 if(action==='add-product')editProduct();
 if(action==='retry')await init();
 if(action==='signout'){try{if(state.emailIdentityEnabled)await (await identityClient()).logout();await api('/signout',{});state.user=null;state.admin=null;state.lastVote=null;dismissSharePrompt();$('#modal').close();await refresh();resetQueue();await render();toast('You’re signed out.');}catch(err){toast(err.message);}}
});
$('#account-button').addEventListener('click',()=>{if(!state.user){auth();return;}openModal(`<h2 id="modal-title">${esc(accountLabel())}</h2><p>Your votes are saved to this account.</p>${state.user.is_admin?'<p><a class="text-button" href="#admin" id="admin-link">Open your admin desk ↗</a></p>':''}<button class="dark wide" data-action="signout">Sign out</button>`);$('#admin-link')?.addEventListener('click',()=>$('#modal').close());});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;$('#search-results').innerHTML=results();}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){state.sort=e.target.value;$('#search-results').innerHTML=results();}});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['submission-form','photo-submission-form','product-form','claim-form'].includes(form.getAttribute('id')))return;e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])');button.disabled=true;const error=form.querySelector('.form-error');error.textContent='';const data=Object.fromEntries(new FormData(form));
 try{

  if(form.getAttribute('id')==='submission-form'){await submitCommunityPhoto(form,data);form.innerHTML='<div class="form-success"><h2>It’s on the list. ✓</h2><p>Your product is waiting for review. Thanks for putting it on our radar.</p><a class="text-button" href="#vote">Back to voting →</a></div>';}
  if(form.getAttribute('id')==='photo-submission-form'){await submitCommunityPhoto(form,data);form.innerHTML='<div class="form-success"><h2>Thank you for sharing your photo!</h2><p>It is waiting for approval before appearing on the product card.</p><a href="#vote">Back to voting →</a></div>';}
  if(form.getAttribute('id')==='product-form'){if(form.dataset.mediaBusy)throw new Error('Wait for the photo or lookup to finish before saving.');await api('/admin/products',{...data,affiliate:data.affiliate==='true',active:data.active==='true'});$('#modal').close();state.admin=null;await refresh();resetQueue();await render();toast('Product saved.');}
  if(form.getAttribute('id')==='claim-form'){const result=await api('/admin/claim',data);state.user=result.user;state.admin=null;updateAccount();await render();toast('Your admin desk is ready.');}
 }catch(err){error.textContent=err.message;}finally{button.disabled=false;}
});
window.addEventListener('hashchange',async()=>{if(await processEmailCallback())return;render();window.scrollTo({top:0});});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){if(e.target.dataset.productPhoto){const p=product(e.target.dataset.productPhoto);if(p){e.target.outerHTML=photoPlaceholder(p);return;}}e.target.replaceWith(Object.assign(document.createElement('div'),{className:'form-note',textContent:'Photo unavailable'}));}},true);
async function init(throwOnError=false){try{const me=await api('/me');state.user=me.user;state.emailIdentityEnabled=me.emailIdentityEnabled;if(me.preview){$('#preview-note').hidden=false;$('#preview-note').textContent='Private development preview · Accounts and votes here are separate from the live site.';}await refresh();resetQueue();await render();}catch(e){if(throwOnError)throw e;$('#main').innerHTML=`<div class="empty"><h1>Almost at the nail desk.</h1><p>${esc(e.message)}</p><button class="pink" data-action="retry">Try again</button></div>`;}}
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 try{Promise.resolve(document.modelContext.registerTool({
  name:'search_nail_products',title:'Search nail products',
  description:'Search the product catalog and show the matching products in Explore. Returns product IDs, brands, names, and real vote counts. Does not cast votes.',
  inputSchema:{type:'object',properties:{query:{type:'string',maxLength:120}},required:['query'],additionalProperties:false},
  annotations:{readOnlyHint:false,untrustedContentHint:true},
  async execute(input){if(!input||typeof input.query!=='string'||input.query.length>120)throw new Error('Enter a search string of at most 120 characters.');state.search=input.query;state.filter='All products';state.sort='new';location.hash='discover';await render();return {products:filtered().map(p=>({id:p.id,name:p.name,brand:p.brand,total:p.total,slayPercent:percent(p)}))};}
 },{signal:lifecycle.signal})).catch(()=>{});}catch{}
}

let refreshingRatings=false;
setInterval(async()=>{if(document.hidden||refreshingRatings||state.busy||!['vote','discover','watchlist'].includes(route()))return;refreshingRatings=true;try{await refresh();if(route()==='watchlist'&&!$('#modal').open){await render();return;}for(const node of document.querySelectorAll('[data-verdict]')){const p=product(node.dataset.verdict);if(p)node.outerHTML=verdictBadge(p);}for(const node of document.querySelectorAll('[data-trend]')){const p=product(node.dataset.trend);if(p)node.outerHTML=trendBadge(p);}if(route()==='discover'&&!$('#modal').open)$('#search-results').innerHTML=results();}catch{}finally{refreshingRatings=false;}},60000);

let bulkBusy=false,userOffset=0,userSearch='';
function bulkDesk(){openModal(`<h2 id="modal-title">Bulk product desk</h2><p>Paste up to 10 HTTPS product links, one per line. Review the details before saving. Some shops require manual details and photos.</p><div class="panel"><h3>Import a spreadsheet · up to 100 products</h3><p>Fill the template in Excel or Google Sheets, then export as CSV (UTF-8). Required: name, brand, category. Optional: url, image, description, affiliate (true/false). Image links must point to photos you have permission to display.</p><a href="/product-import-template.csv" download>Download CSV template ↧</a><label>Upload your CSV<input type="file" accept=".csv,text/csv" id="bulk-csv"></label><p id="bulk-status" role="status" aria-live="polite" style="padding:12px;background:#fff3c4;border-radius:8px">Choose a completed CSV file. The downloaded template contains column headings only—add your products first.</p><p>CSV imports use your supplied details; they do not automatically look up 100 websites. Existing products are never overwritten.</p></div><label>Product links<textarea id="bulk-links" rows="6" placeholder="https://…"></textarea></label><button type="button" class="pink" data-action="bulk-prepare">Prepare products</button><div id="bulk-rows"></div><button type="button" class="pink wide" data-action="bulk-save" hidden>Save selected products</button>`);}
async function prepareBulk(){const urls=[...new Set($('#bulk-links').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];const status=$('#bulk-status');if(!urls.length||urls.length>10){status.textContent='Enter between 1 and 10 different product links.';return;}if($('#bulk-rows').children.length){status.textContent='Close and reopen the desk to start another batch. Your current rows are kept here.';return;}if(urls.some(x=>{try{return new URL(x).protocol!=='https:';}catch{return true;}})){status.textContent='Every link must start with https://.';return;}
 $('#bulk-rows').innerHTML=urls.map((url,i)=>`<details class="panel bulk-row" open><summary>Product ${i+1}</summary><form data-bulk-row><label class="bulk-select"><input type="checkbox" data-selected checked> Include this product</label>${fields({url},true)}<label>Purchase link type<select name="affiliate"><option value="false">Standard product link</option><option value="true">Affiliate link (disclosed to visitors)</option></select></label><p class="form-error" role="alert"></p><p data-row-status role="status">Ready for lookup</p></form></details>`).join('');
 $('[data-action="bulk-save"]').hidden=false;bulkBusy=true;status.textContent='Looking up products…';
 try{for(const form of document.querySelectorAll('[data-bulk-row]')){if(!form.isConnected)break;const note=form.querySelector('[data-row-status]');try{const d=await api('/admin/lookup',{url:form.elements.url.value});if(!form.isConnected)break;for(const key of ['name','brand','description'])if(!form.elements[key].value.trim()&&d[key])form.elements[key].value=d[key];if(!form.elements.image.value&&d.images?.length)form.elements.image.value=d.images[0];showPhoto(form);note.textContent=d.message+' Review all fields and the photo.';}catch(e){note.textContent=e.message+' You can fill this row manually.';}}}finally{bulkBusy=false;status.textContent='Review each selected product, then save. Missing names, brands, and duplicate products will be flagged.';}}
async function saveBulk(){const status=$('#bulk-status');if(bulkBusy){status.textContent='Wait for the lookups to finish.';return;}const forms=[...document.querySelectorAll('[data-bulk-row]')].filter(f=>!f.dataset.saved&&f.querySelector('[data-selected]').checked);if(!forms.length){status.textContent='Select at least one unsaved product.';return;}if(forms.some(f=>f.dataset.mediaBusy)){status.textContent='Wait for photo uploads or lookups to finish.';return;}bulkBusy=true;let saved=0;const button=$('[data-action="bulk-save"]');button.disabled=true;
 try{for(const form of forms){const data=Object.fromEntries(new FormData(form));const note=form.querySelector('[data-row-status]');const problems=bulkProblems(form);if(problems.length){note.textContent=problems.join(' ');form.closest('details').open=true;continue;}status.textContent=`Saving product ${forms.indexOf(form)+1} of ${forms.length}…`;try{await api('/admin/products',{...data,affiliate:data.affiliate==='true',active:true});form.dataset.saved='true';saved++;note.textContent='Saved ✓';form.querySelectorAll('input,textarea,select,button').forEach(n=>n.disabled=true);form.closest('details').open=false;form.closest('details').querySelector('summary').textContent=data.brand+' · '+data.name+' · Saved ✓';}catch(e){note.textContent=e.message;form.closest('details').open=true;}}state.admin=null;await refresh();await render();status.textContent=`Saved ${saved} of ${forms.length} selected products. Any unsuccessful rows remain editable; retrying will skip saved rows.`;}catch(e){status.textContent=e.message;}finally{bulkBusy=false;button.disabled=false;}}
async function usersDesk(){openModal(`<h2 id="modal-title">Users</h2><p>Private account list. Password reset links are emailed directly to the account owner.</p><form id="user-search-form"><label>Find email or username<input name="query" value="${esc(userSearch)}" maxlength="254"></label><button type="submit">Search users</button></form><div id="users-list" aria-live="polite">Loading…</div>`);await loadUsers();}
async function loadUsers(){const target=$('#users-list');try{const d=await api('/admin/users?search='+encodeURIComponent(userSearch)+'&offset='+userOffset);if(!target.isConnected)return;target.innerHTML=d.users.slice(0,50).map(u=>`<div class="admin-row"><div><strong>@${esc(u.username)}${u.is_admin?' · Admin':''}</strong><p>${esc(u.email)}</p><p>Joined ${esc(new Date(u.created_at).toLocaleDateString())} · ${u.vote_count} votes</p></div><button type="button" data-reset-email="${esc(u.email)}">Send password reset email</button></div>`).join('')||'<p>No users found.</p>';target.innerHTML+=`<div class="actions">${userOffset?'<button data-action="users-prev">Previous</button>':''}${d.users.length>50?'<button data-action="users-next">Next</button>':''}</div>`;}catch(e){target.textContent=e.message;}}
document.addEventListener('submit',async e=>{const form=e.target;if(form.matches('[data-bulk-row]')){e.preventDefault();return;}if(form.id==='user-search-form'){e.preventDefault();userSearch=form.elements.query.value.trim();userOffset=0;await loadUsers();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.action;if(action==='bulk-open')bulkDesk();if(action==='bulk-prepare')await prepareBulk();if(action==='bulk-save')await saveBulk();if(action==='users-open'){userOffset=0;await usersDesk();}if(action==='users-prev'){userOffset=Math.max(0,userOffset-50);await loadUsers();}if(action==='users-next'){userOffset+=50;await loadUsers();}if(b.dataset.resetEmail)emailAuth('forgot',b.dataset.resetEmail);});
document.addEventListener('click',e=>{if(bulkBusy&&e.target.closest('[data-action="close"]')){e.preventDefault();e.stopImmediatePropagation();toast('Wait for the current batch to finish.');}},true);
$('#modal').addEventListener('cancel',e=>{if(bulkBusy){e.preventDefault();toast('Wait for the current batch to finish.');}});

document.addEventListener('change',async e=>{if(e.target.id!=='bulk-csv')return;const input=e.target,status=$('#bulk-status');if(bulkBusy||$('#bulk-rows').children.length){status.textContent='Finish this batch, then close and reopen the desk to import another file.';input.value='';return;}const file=input.files[0];if(!file)return;status.textContent='Reading '+file.name+'…';try{if(/\.(xlsx?|numbers|ods)$/i.test(file.name))throw new Error('This is a workbook. In Excel or Google Sheets, save or download it as CSV, then choose that file.');if(file.size>1000000)throw new Error('Choose a CSV file smaller than 1 MB.');const csvText=await file.text();if(csvText.startsWith('PK')||csvText.includes('\u0000'))throw new Error('This looks like a workbook rather than CSV text. Export it as CSV UTF-8 from your spreadsheet app.');const products=parseProductCSV(csvText);if(!input.isConnected)return;$('#bulk-rows').innerHTML=products.map((p,i)=>`<details class="panel bulk-row"><summary>${i+1}. ${esc(p.brand||'Missing brand')} · ${esc(p.name||'Missing name')}</summary><form data-bulk-row><label class="bulk-select"><input type="checkbox" data-selected checked> Include this product</label>${fields(p,true)}<label>Purchase link type<select name="affiliate"><option value="false">Standard product link</option><option value="true" ${p.affiliate?'selected':''}>Affiliate link (disclosed to visitors)</option></select></label><p class="form-error" role="alert"></p><p class="form-note">${esc((p.issues||[]).join(' '))}</p><p data-row-status role="status">Ready for review</p><button type="button" data-action="remove-bulk-row">Remove row</button></form></details>`).join('');$('[data-action="bulk-save"]').hidden=false;reviewBulkRows();status.textContent=products.length+' products loaded. Expand rows to review or edit, uncheck any you want to skip, then save selected products.';}catch(err){status.textContent='Could not import '+file.name+': '+err.message;status.scrollIntoView({block:'nearest'});}finally{input.value='';}});

function bulkProblems(form){const d=Object.fromEntries(new FormData(form)),errors=[];if(!d.name?.trim())errors.push('Add a product name.');if(!d.brand?.trim())errors.push('Add a brand.');if(!d.category?.trim())errors.push('Add a category.');for(const key of ['url','image'])if(d[key]){if(key==='image'&&/^\/api\/images\/[a-f0-9-]{36}\.webp$/.test(d[key]))continue;try{const u=new URL(d[key]);if(u.protocol!=='https:'||u.username||u.password)throw 0;}catch{errors.push('Fix the '+key+' link or clear it; use HTTPS.');}}for(const [key,max] of Object.entries({name:120,brand:80,category:40,description:1500,url:2000,image:2000}))if((d[key]||'').length>max)errors.push('Shorten '+key+' to '+max+' characters.');const identity=p=>(p.brand||'').trim().toLowerCase()+'\n'+(p.name||'').trim().toLowerCase();const existing=state.admin?.products||state.products;if(d.name&&d.brand&&existing.some(p=>identity(p)===identity(d)))errors.push('Already in your catalog. Remove this row or change the name/brand.');const earlier=[...document.querySelectorAll('[data-bulk-row]')];for(const f of earlier){if(f===form)break;if((f.dataset.saved||f.querySelector('[data-selected]')?.checked)&&identity(Object.fromEntries(new FormData(f)))===identity(d)){errors.push('Duplicate of an earlier selected row. Remove or uncheck one copy, or edit it.');break;}}return errors;}
function reviewBulkRows(){for(const form of document.querySelectorAll('[data-bulk-row]')){if(form.dataset.saved)continue;const issues=bulkProblems(form);form.querySelector('[data-row-status]').textContent=issues.length?issues.join(' '):'Ready to save';form.closest('details').querySelector('summary').textContent=(issues.length?'Needs attention · ':'Ready · ')+(form.elements.brand.value||'Missing brand')+' · '+(form.elements.name.value||'Missing name');}}
document.addEventListener('change',e=>{if(e.target.closest('[data-bulk-row]')&&!bulkBusy)reviewBulkRows();});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="remove-bulk-row"]')&&!bulkBusy){e.target.closest('details').remove();reviewBulkRows();}});

const sheetColumns=['name','brand','category','url','image','description','affiliate','active'];let sheetSaving=false;
function categoryOptions(){let list=document.querySelector('#category-options');if(!list){list=document.createElement('datalist');list.id='category-options';document.body.append(list);}list.innerHTML=[...new Set([...categories,...(state.admin?.products||[]).map(p=>p.category)])].map(c=>`<option value="${esc(c)}"></option>`).join('');}
function sheetDesk(){categoryOptions();openModal(`<h2 id="modal-title">Product sheet</h2><p>Copy cells from Excel or Google Sheets and paste below. Include column headings, or use this order: name, brand, category, url, image, description, affiliate, active. Up to 100 rows. Type any new category; it becomes available when saved.</p><label>Paste spreadsheet cells<textarea id="sheet-paste" rows="5" placeholder="Paste your cells here…"></textarea></label><button data-action="sheet-preview">Load pasted rows</button><hr><label>Edit category<select id="sheet-category"><option value="">Edit All</option>${[...new Set((state.admin?.products||[]).map(p=>p.category))].sort().map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select></label><label>Existing product batch<select id="sheet-batch">${Array.from({length:Math.max(1,Math.ceil((state.admin?.products.length||0)/100))},(_,i)=>`<option value="${i}">${i*100+1}–${Math.min((i+1)*100,state.admin?.products.length||0)}</option>`).join('')}</select></label><button data-action="sheet-existing">Load existing products to edit</button><p>Loading another sheet replaces unsaved rows in this desk. Existing-product edits keep their votes. Removing a row here only excludes it from this save.</p><div class="actions"><button type="button" data-action="sheet-sort-asc">Category A–Z ↓</button><button type="button" data-action="sheet-sort-desc">Category Z–A ↑</button></div><p class="form-note">Sorts the rows currently loaded, including your unsaved category edits. Blank categories appear last.</p><p id="sheet-status" role="status"></p><div style="overflow:auto;max-height:55vh"><table id="product-sheet"><thead><tr><th>Save?</th>${sheetColumns.map(k=>`<th>${k}</th>`).join('')}<th>Result</th><th>Remove</th></tr></thead><tbody></tbody></table></div><p>Active = false hides a product and stops new votes while keeping its data.</p><div class="actions"><button class="pink" data-action="sheet-save">Save selected rows</button><button data-action="sheet-delete">Permanently delete selected products</button></div><div id="sheet-confirm" role="status"></div><details class="panel"><summary>Rename or remove a category</summary><p>Choose a category above. Enter a new name to rename it, or an existing category to move all its products there and remove the old category. Products and votes are preserved.</p><label>New name / destination category<input id="category-destination" maxlength="40" list="category-options"></label><button data-action="category-move">Review category change</button></details>`);}
function showSheet(products,editing=false){$('#product-sheet tbody').innerHTML=products.map(p=>`<tr data-sheet-row data-id="${editing?esc(p.id):''}"><td><input type="checkbox" data-sheet-selected checked aria-label="Include row"></td>${sheetColumns.map(k=>`<td>${['affiliate','active'].includes(k)?`<select data-col="${k}" aria-label="${k}"><option value="false" ${p[k]===false||k==='affiliate'&&!p[k]?'selected':''}>false</option><option value="true" ${p[k]===true||k==='active'&&p[k]!==false?'selected':''}>true</option></select>`:`<textarea rows="2" data-col="${k}" aria-label="${k}" ${k==='category'?'placeholder="Type category"':''}>${esc(p[k]||'')}</textarea>${k==='image'?sheetPhoto(p.image):''}`}</td>`).join('')}<td data-sheet-result>${editing?'Editing existing product':'New product'}</td><td><button data-action="sheet-remove">Remove from sheet</button>${editing?'<button data-action="sheet-delete-one">Delete product</button>':''}</td></tr>`).join('');$('#sheet-status').textContent=products.length+' rows loaded. Edit any cell, then save. Nothing is saved yet.';}
async function sheetSave(){if(sheetSaving)return;const rows=[...document.querySelectorAll('[data-sheet-row]')].filter(r=>!r.dataset.saved&&r.querySelector('[data-sheet-selected]').checked);if(!rows.length){$('#sheet-status').textContent='Select an unsaved row first.';return;}sheetSaving=true;let saved=0;try{for(const row of rows){const data=Object.fromEntries([...row.querySelectorAll('[data-col]')].map(n=>[n.dataset.col,n.value.trim()]));const result=row.querySelector('[data-sheet-result]');const missing=['name','brand','category'].filter(k=>!data[k]);if(missing.length){result.textContent='Add: '+missing.join(', ');continue;}const limits={name:120,brand:80,category:40,url:2000,image:2000,description:1500};const long=Object.keys(limits).filter(k=>data[k].length>limits[k]);if(long.length){result.textContent='Too long: '+long.join(', ');continue;}$('#sheet-status').textContent=`Saving ${rows.indexOf(row)+1} of ${rows.length}…`;try{await api('/admin/products',{...data,...(row.dataset.id?{id:row.dataset.id}:{}),affiliate:data.affiliate==='true',active:data.active==='true'});row.dataset.saved='true';row.querySelectorAll('input,textarea,select,button').forEach(n=>n.disabled=true);result.textContent='Saved ✓';saved++;}catch(e){result.textContent=e.message;}}state.admin=null;await refresh();await render();categoryOptions();$('#sheet-status').textContent=`Saved ${saved} of ${rows.length}. Fix or remove unsuccessful rows, then retry. Saved rows are skipped.`;}catch(e){$('#sheet-status').textContent=e.message;}finally{sheetSaving=false;}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(a==='sheet-open')sheetDesk();if(sheetSaving)return;if(a==='sheet-preview'){try{let t=$('#sheet-paste').value;if(!t.trim())throw new Error('Paste your spreadsheet cells first.');const first=t.split(/\r?\n/)[0].toLowerCase().split('\t').map(s=>s.trim());if(!first.includes('name')&&!first.includes('product name')){const count=first.length;if(count>8)throw new Error('Use up to 8 columns, or include column headings.');t=sheetColumns.slice(0,count).join('\t')+'\n'+t;}const p=parseProductCSV(t,'\t').map(p=>({...p,active:! /^(false|no)$/i.test(p.active||'')}));showSheet(p);}catch(err){$('#sheet-status').textContent=err.message;}}if(a==='sheet-existing')showSheet(sheetCategoryProducts().slice(Number($('#sheet-batch').value)*100,Number($('#sheet-batch').value)*100+100),true);if(a==='sheet-remove')b.closest('tr').remove();if(a==='sheet-save')await sheetSave();});
document.addEventListener('click',e=>{if(sheetSaving&&e.target.closest('button')&&!e.target.closest('[data-action="sheet-save"]')){e.preventDefault();e.stopImmediatePropagation();}},true);
$('#modal').addEventListener('cancel',e=>{if(sheetSaving)e.preventDefault();});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="add-product"],[data-edit],[data-action="bulk-open"]'))categoryOptions();});

document.addEventListener('click',e=>{const action=e.target.closest('button')?.dataset.action;if(!['sheet-sort-asc','sheet-sort-desc'].includes(action)||sheetSaving)return;const body=$('#product-sheet tbody');const rows=[...body.querySelectorAll('[data-sheet-row]')];const value=(row,key)=>row.querySelector('[data-col="'+key+'"]').value.trim();const direction=action==='sheet-sort-asc'?1:-1;rows.sort((a,b)=>{const ca=value(a,'category'),cb=value(b,'category');if(!ca||!cb)return ca?-1:cb?1:0;return direction*ca.localeCompare(cb,undefined,{sensitivity:'base',numeric:true})||value(a,'name').localeCompare(value(b,'name'),undefined,{sensitivity:'base',numeric:true});});for(const row of rows)body.append(row);$('#sheet-status').textContent=rows.length?'Sorted '+rows.length+' rows by category. Your edits and selections are kept.':'Load products or paste rows first.';});
function sheetCategoryProducts(){const category=$('#sheet-category')?.value||'';return (state.admin?.products||[]).filter(p=>!category||p.category===category);}
function sheetPhoto(url){if(!url)return '<div class="sheet-photo">No image</div>';if(!/^https:\/\//i.test(url)&&!/^\/api\/images\/[a-f0-9-]{36}\.webp$/.test(url))return '<div class="sheet-photo">Image unavailable</div>';return `<div class="sheet-photo"><img src="${esc(url)}" alt="Product preview" loading="lazy" referrerpolicy="no-referrer" style="width:80px;height:80px;object-fit:contain"></div>`;}
let sheetConfirmAction=null;
document.addEventListener('change',e=>{if(e.target.id==='sheet-category'&&!sheetSaving){const n=sheetCategoryProducts().length;$('#sheet-batch').innerHTML=Array.from({length:Math.max(1,Math.ceil(n/100))},(_,i)=>`<option value="${i}">${i*100+1}–${Math.min((i+1)*100,n)}</option>`).join('');$('#sheet-status').textContent='Click Load existing products to edit to load this category. Current edits remain until you load.';}if(e.target.matches('[data-col="image"]')){const old=e.target.parentElement.querySelector('.sheet-photo');if(old)old.outerHTML=sheetPhoto(e.target.value.trim());}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.closest('.sheet-photo'))e.target.closest('.sheet-photo').textContent='Image unavailable';},true);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||sheetSaving)return;const action=b.dataset.action,box=$('#sheet-confirm');if(action==='sheet-delete'||action==='sheet-delete-one'){const rows=action==='sheet-delete-one'?[b.closest('tr')]:[...document.querySelectorAll('[data-sheet-row]')].filter(r=>r.querySelector('[data-sheet-selected]').checked);const ids=rows.map(r=>r.dataset.id).filter(Boolean);if(!ids.length){$('#sheet-status').textContent='Load existing products and select the products to delete.';return;}sheetConfirmAction={kind:'delete',ids};box.innerHTML=`<p><strong>Permanently delete ${ids.length} products and all their votes?</strong> This cannot be undone.</p><ul>${ids.map(id=>{const p=state.admin?.products.find(p=>p.id===id);return `<li>${esc(p?p.brand+' · '+p.name:id)}</li>`;}).join('')}</ul><button data-action="sheet-confirm">Yes, permanently delete</button> <button data-action="sheet-cancel">Cancel</button>`;box.scrollIntoView({block:'nearest'});}
 if(action==='category-move'){const from=$('#sheet-category').value,to=$('#category-destination').value.trim();if(!from||!to||from===to){$('#sheet-status').textContent='Choose one category and a different destination name.';return;}sheetConfirmAction={kind:'category',from,to};box.innerHTML=`<p>Move all ${sheetCategoryProducts().length} products from <strong>${esc(from)}</strong> to <strong>${esc(to)}</strong>? Unsaved sheet edits will be replaced by the updated catalog.</p><button data-action="sheet-confirm">Confirm category change</button> <button data-action="sheet-cancel">Cancel</button>`;box.scrollIntoView({block:'nearest'});}
 if(action==='sheet-cancel'){sheetConfirmAction=null;box.textContent='';}if(action==='sheet-confirm'&&sheetConfirmAction){const plan=sheetConfirmAction;sheetConfirmAction=null;sheetSaving=true;try{if(plan.kind==='delete'){const d=await api('/admin/delete-products',{ids:plan.ids});for(const row of document.querySelectorAll('[data-sheet-row]'))if(d.deleted.includes(row.dataset.id))row.remove();box.textContent=d.deleted.length+' products permanently deleted.';}else{const d=await api('/admin/category',{from:plan.from,to:plan.to});box.textContent=d.updated+' products moved to '+plan.to;$('#product-sheet tbody').innerHTML='';}state.admin=await api('/admin/data');await refresh();await render();categoryOptions();const select=$('#sheet-category');select.innerHTML='<option value="">Edit All</option>'+[...new Set(state.admin.products.map(p=>p.category))].sort().map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');const n=state.admin.products.length;$('#sheet-batch').innerHTML=Array.from({length:Math.max(1,Math.ceil(n/100))},(_,i)=>`<option value="${i}">${i*100+1}–${Math.min((i+1)*100,n)}</option>`).join('');}catch(err){box.textContent=err.message;}finally{sheetSaving=false;}}});

function voteCategoryControl(){const options=[...new Set(state.products.map(p=>p.category))].sort((a,b)=>a.localeCompare(b));return '<div class="vote-category-control"><label for="vote-category">What are we voting on?</label><select id="vote-category" '+(state.busy?'disabled':'')+'><option value="">Vote all</option>'+options.map(c=>'<option value="'+esc(c)+'" '+(state.voteCategory===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select><p>Only products you haven’t voted on. Skip anything you haven’t tried.</p></div>';}
function skipProduct(){if(state.busy||!product(state.queue[state.index])||!$('#voting-surface')||$('#modal').open)return;state.index++;$('#voting-surface').innerHTML=voteCard();toast('Skipped — no vote cast.');}
document.addEventListener('change',e=>{if(e.target.id!=='vote-category')return;if(state.busy){e.target.value=state.voteCategory;return;}state.voteCategory=e.target.value;resetQueue();$('#voting-surface').innerHTML=voteCard();});
let swipeStart=null;
document.addEventListener('pointerdown',e=>{const stage=e.target.closest('[data-swipe-skip]');if(!stage||e.target.closest('a,button,input,select')||state.busy||!e.isPrimary||e.button!==0||$('#modal').open)return;swipeStart={id:e.pointerId,x:e.clientX,y:e.clientY,stage,product:state.queue[state.index]};stage.setPointerCapture(e.pointerId);});
document.addEventListener('pointerup',e=>{const start=swipeStart;if(!start||start.id!==e.pointerId)return;swipeStart=null;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(start.stage.isConnected&&start.product===state.queue[state.index]&&Math.abs(dx)>=60&&Math.abs(dx)>Math.abs(dy)*1.5){if(dx<0)skipProduct();else previousProduct();}});
document.addEventListener('pointercancel',()=>{swipeStart=null;});
document.addEventListener('dragstart',e=>{if(e.target.closest('[data-swipe-skip]'))e.preventDefault();});

function voteEditButtons(p){return '<div class="vote-actions">'+[['slay','Gloss'],['nay','Toss']].map(([value,label])=>'<button data-change-vote="'+value+'" data-id="'+esc(p.id)+'" aria-pressed="'+(p.my_vote===value)+'" '+(p.my_vote===value?'disabled':'')+'>'+voteSymbol(value)+label+(p.my_vote===value?' ✓':'')+'</button>').join('')+'</div>';}
function myVotes(){if(!state.user)return '<div class="empty"><h1>My Votes</h1><p>Sign in to see and update your votes.</p><button data-action="signin" class="pink">Sign in</button></div>';const list=state.products.filter(p=>p.my_vote);return '<div class="eyebrow">Your experience can change</div><h1>My <em>Votes.</em></h1><p class="muted">Choose Gloss or Toss to replace your saved vote. You always count once per product.</p><div class="my-votes-grid">'+(list.length?list.map(p=>'<article class="panel"><div class="my-vote-product">'+photo(p)+'<div><div class="brand">'+esc(p.brand)+' · '+esc(p.category)+'</div><h2>'+esc(p.name)+'</h2><button class="text-button" data-detail="'+esc(p.id)+'">Product details ↗</button></div></div>'+voteEditButtons(p)+shareButton(p)+'</article>').join(''):'<div class="empty"><h2>No votes yet.</h2><p>Vote on products you’ve tried, then find your choices here.</p><a href="#vote">Start voting →</a></div>')+'</div>';}
async function changeVote(id,choice){if(state.busy)return;if(route()==='vote'&&matchMedia('(max-width:680px)').matches)document.body.classList.add('focus-vote');state.busy=true;document.querySelectorAll('[data-change-vote]').forEach(b=>b.disabled=true);try{await api('/vote/change',{product_id:id,choice});await refresh();await render();if($('#modal').open)detail(id);toast('Vote changed to '+(choice==='slay'?'Gloss':'Toss')+' — still one vote.');}catch(e){toast(e.message);await render();if($('#modal').open)detail(id);}finally{state.busy=false;}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="focus-vote"]')){const enabled=document.body.classList.toggle('focus-vote');e.target.closest('button').textContent=enabled?'Exit focus view ×':'Focus view ⛶';}});

function previousProduct(){if(state.busy||!$('#voting-surface')||$('#modal').open)return;if(state.index<=0){toast('You’re at the first product.');return;}state.index--;$('#voting-surface').innerHTML=voteCard();toast('Previous product — no vote cast.');}

function profilePage(){if(!state.user)return '<div class="empty"><h1>Your profile</h1><p>Sign in to manage your account and see your votes.</p><button class="pink" data-action="signin">Sign in or sign up</button></div>';return '<div class="eyebrow">Your nail community account</div><h1>Your <em>Profile.</em></h1><section class="panel"><h2>'+esc(accountLabel())+'</h2><p class="muted">Your opinions. Your saved votes.</p>'+emailProfile()+'<p><a class="pink profile-link" href="#watchlist">My Watchlist →</a></p><p><a class="pink profile-link" href="#my-votes">My Votes →</a></p>'+(state.user.is_admin?'<p><a href="#admin">Open product admin →</a></p>':'')+'<button data-action="signout">Sign out</button></section><p><a href="https://www.tiktok.com/@gloss.or.toss" target="_blank" rel="noopener noreferrer">TikTok · @gloss.or.toss</a></p>';}


async function identityClient(){return import('./identity-client.js');}
let verificationAttempt=null;
function emailProfile(){return state.user?.email_verified?'<p>Email verified · '+esc(state.user.email)+'</p><button data-email-mode="forgot">Reset password by email</button>':'';}
function emailAuth(mode='choose',email=''){
 verificationAttempt=null;
 if(!['signin','signup','forgot'].includes(mode)){
  openModal('<h2 id="modal-title">Welcome to Gloss or Toss</h2><div class="actions"><button class="pink" data-email-mode="signin">Sign In</button><button data-email-mode="signup">Sign Up</button></div>');return;
 }
 const signup=mode==='signup',forgot=mode==='forgot';
 openModal(`<h2 id="modal-title">${signup?'Sign Up':forgot?'Forgot password?':'Sign In'}</h2>${forgot?'<p>Enter your email and we’ll send you a password reset link.</p>':''}<form id="email-auth-form" data-mode="${mode}"><label>Email<input name="email" type="email" autocomplete="email" autocapitalize="none" spellcheck="false" required maxlength="254" value="${esc(email||state.user?.email||'')}"></label>${forgot?'':'<label>Password'+(signup?' <small>· at least 8 characters</small>':'')+'<input name="password" type="password" required minlength="8" maxlength="128" autocomplete="'+(signup?'new-password':'current-password')+'"></label>'}<p class="form-error" role="alert"></p><button type="submit" class="pink wide">${signup?'Sign Up':forgot?'Send reset email':'Sign In'}</button></form><div class="modal-bottom">${!signup&&!forgot?'<button class="text-button" data-email-mode="forgot">Forgot password?</button>':''}<button class="text-button" data-email-mode="${signup||forgot?'signin':'signup'}">${signup?'Already a member? Sign in here':forgot?'Back to Sign In':'Not a member? Sign up'}</button></div>`);
}
function verificationScreen(sent=true){
 const email=verificationAttempt?.email||'';
 openModal(`<h2 id="modal-title">${sent?'Verify your email':'Your email hasn’t been verified yet.'}</h2><p>${sent?'We sent a verification link to '+esc(email)+'. Please check your inbox before signing in.':'Check your inbox for the verification link sent to '+esc(email)+', or request another below.'}</p><p class="form-note">Check spam or junk too. Allow a few minutes for the email to arrive.</p><p class="form-error" role="alert"></p><p id="verification-status" role="status"></p><div class="actions"><button class="pink" data-resend-verification>Resend verification email</button><button data-email-mode="signin">Back to Sign In</button></div>`);
}
function emailPasswordForm(inviteToken){openModal(`<h2 id="modal-title">Set your password</h2><form id="email-password-form"><label>New password <small>· at least 8 characters</small><input name="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><label>Confirm password<input name="confirmation" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label><p class="form-error" role="alert"></p><button type="submit" class="pink wide">Save password</button></form>`);$('#email-password-form').inviteToken=inviteToken;}
function authError(e){
 const message=e?.message||'The request could not be completed. Please try again.';
 if(/fetch|network|timed? ?out/i.test(message))return 'We couldn’t reach the email service. Please try again.';
 if(/confirmation mail|sending.*mail|recovering user/i.test(message))return 'The email service could not send your email. Please try again shortly. If this continues, contact glossortossapp@gmail.com.';
 return message;
}
async function emailSignedIn(message='Signed in. Your votes are ready.'){
 const client=await identityClient();
 await client.getUser();
 await api('/identity/session',{});
 await init(true);
 if(!state.user)throw new Error('Your session could not be confirmed. Please sign in again.');
 verificationAttempt=null;$('#modal').close();location.hash='profile';await render();toast(message);
}
async function processEmailCallback(){
 const params=new URLSearchParams(location.hash.slice(1));
 if(!['confirmation_token','recovery_token','invite_token','email_change_token','access_token','error','error_description'].some(k=>params.has(k)))return false;
 try{
  if(params.has('error')||params.has('error_description')){history.replaceState(null,'',location.pathname+location.search+'#profile');throw new Error(params.get('error_description')||'This email link has expired. Request a new one.');}
  const result=await (await identityClient()).handleAuthCallback();
  if(result?.type==='recovery'){emailPasswordForm();return true;}
  if(result?.type==='invite'){emailPasswordForm(result.token);return true;}
  if(!result)throw new Error('This email link is invalid or expired.');
  await emailSignedIn(result.type==='confirmation'?'Email verified successfully. You’re signed in.':'Your account is ready.');
 }catch(e){
  // Drop failed tokens too, so reloading cannot keep replaying an expired link.
  history.replaceState(null,'',location.pathname+location.search+'#profile');
  openModal('<h2 id="modal-title">This email link couldn’t be completed</h2><p>'+esc(authError(e))+'</p><p>Sign in to resend verification, or request another password reset email.</p><button data-email-mode="signin">Sign In</button><button data-email-mode="forgot">Forgot password?</button>');
 }
 return true;
}
document.addEventListener('click',async e=>{
 const mode=e.target.closest('[data-email-mode]');if(mode){emailAuth(mode.dataset.emailMode);return;}
 const button=e.target.closest('[data-resend-verification]');if(!button)return;
 const error=$('#modal .form-error'),status=$('#verification-status'),attempt=verificationAttempt;
 if(!attempt){emailAuth('signin');return;}
 error.textContent='';
 if(Date.now()<attempt.nextSend){status.textContent='Please wait '+Math.ceil((attempt.nextSend-Date.now())/1000)+' seconds before resending.';return;}
 button.disabled=true;
 try{
  // GoTrue resends signup confirmation for an existing, unconfirmed email.
  // It keeps the original password; these credentials stay in memory only.
  await (await identityClient()).signup(attempt.email,attempt.password);
  attempt.nextSend=Date.now()+60000;status.textContent='Verification email sent. Check your inbox.';
 }catch(e){error.textContent=authError(e);}finally{button.disabled=false;}
});
$('#modal').addEventListener('close',()=>{verificationAttempt=null;});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['email-auth-form','email-password-form'].includes(form.id))return;
 e.preventDefault();const button=form.querySelector('[type="submit"]'),error=form.querySelector('.form-error'),data=Object.fromEntries(new FormData(form));
 button.disabled=true;error.textContent='';
 try{
  const client=await identityClient();
  if(form.id==='email-password-form'){
   if(data.password!==data.confirmation)throw new Error('The passwords don’t match.');
   if(data.password.length<8)throw new Error('Use at least 8 characters.');
   if(form.inviteToken)await client.acceptInvite(form.inviteToken,data.password);else await client.updateUser({password:data.password});
   await emailSignedIn('Password updated. You’re signed in.');
  }else{
   const email=data.email.trim().toLowerCase();
   if(form.dataset.mode==='signup'){
    const settings=await client.getSettings();
    if(settings.disableSignup||settings.autoconfirm||!settings.providers.email)throw new Error('Verified email signup is temporarily unavailable. Please try again later.');
    await client.signup(email,data.password);
    verificationAttempt={email,password:data.password,nextSend:Date.now()+60000};
    verificationScreen();
   }else if(form.dataset.mode==='forgot'){
    await client.requestPasswordRecovery(email);
    openModal('<h2 id="modal-title">Password reset email sent</h2><p>Check your inbox for a link to reset your password. If that email isn’t registered, no email will be sent.</p><button data-email-mode="signin">Back to Sign In</button>');
   }else{
    await client.logout();
    try{await api('/email-signin',{email,password:data.password});}
    catch(e){if(e.code==='EMAIL_UNVERIFIED'){verificationAttempt={email,password:data.password,nextSend:0};verificationScreen(false);return;}throw e;}
    await emailSignedIn();
   }
  }
 }catch(e){if(error.isConnected)error.textContent=authError(e);else toast(authError(e));}
 finally{button.disabled=false;}
});
async function startAuthentication(){
 const handled=await processEmailCallback();
 if(handled){if(!state.products.length)await init();return;}
 try{const client=await identityClient();if(await client.getUser())await api('/identity/session',{});}
 catch(e){toast(authError(e));}
 await init();
}

function watchButton(p){return `<button type="button" class="watch-button" data-watch="${esc(p.id)}" aria-pressed="${!!p.watching}" aria-label="${p.watching?'Remove from':'Add to'} watchlist: ${esc(p.name)}"><svg width="18" height="20" viewBox="0 0 24 24" fill="${p.watching?'currentColor':'none'}" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4z"/></svg>${p.watching?'Watching':'Watchlist'}</button>`;}
function watchlistPage(){if(!state.user)return '<h1>My Watchlist</h1><p>Sign in to save products and follow their scores across devices.</p><button data-action="signin">Sign in or sign up</button>';const list=state.products.filter(p=>p.watching);return `<div class="eyebrow">Before you buy</div><h1>My <em>Watchlist.</em></h1><p>Your private list of products to follow. Saving never casts a vote. Scores and trends reflect the latest community votes.</p><p><a href="#profile">← Profile</a> · ${list.length} products</p><div class="my-votes-grid">${list.length?list.map(p=>`<article class="panel"><div class="my-vote-product">${photo(p)}<div><div class="brand">${esc(p.brand)} · ${esc(p.category)}</div><h2>${esc(p.name)}</h2>${verdictBadge(p)}<p><strong>${result(p)}</strong> · ${votes(p)}</p>${trendBadge(p)}</div></div><div class="actions"><button data-detail="${esc(p.id)}">Product details ↗</button>${watchButton(p)}</div></article>`).join(''):'<div class="empty"><h2>Keep an eye on your next find.</h2><p>Tap Watchlist on a voting card or in product details to save it here. Hidden or deleted products won’t appear.</p><a href="#discover">Explore products →</a></div>'}</div>`;}
const watchBusy=new Set();
document.addEventListener('click',async e=>{const b=e.target.closest('[data-watch]');if(!b)return;const id=b.dataset.watch,p=product(id);if(!p||watchBusy.has(id))return;if(!state.user){auth();return;}watchBusy.add(id);b.disabled=true;try{const d=await api('/watchlist',{product_id:id,watching:!p.watching});p.watching=d.watching;await render();if($('#modal').open)detail(id);toast(d.watching?'Saved to your Watchlist. No vote cast.':'Removed from your Watchlist.');}catch(err){toast(err.message);}finally{watchBusy.delete(id);b.disabled=false;}});

function shareButton(p,iconOnly=false){return `<button type="button" class="product-share ${iconOnly?'share-icon':''}" data-share="${esc(p.id)}" aria-label="Share ${esc(p.name)}" title="Share product"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 16V3m-4 4 4-4 4 4M5 12v9h14v-9"/></svg>${iconOnly?'':' Share'}</button>`;}
function sharedProductPage(id){const p=product(id);if(!p)return '<div class="empty"><h1>Product unavailable</h1><p>This product may have been removed or hidden.</p><a href="#discover">Explore products →</a></div>';return `<section class="shared-product panel"><div class="brand">${esc(p.brand)} · ${esc(p.category)}</div><h1>${esc(p.name)}</h1>${photo(p,'shared-product-photo')}<p>${esc(p.description)}</p><div class="actions">${watchButton(p)}${shareButton(p)}</div>${p.my_vote?'<p>Your current vote</p>'+voteEditButtons(p):`<div class="vote-actions"><button data-vote="slay" data-id="${esc(p.id)}">${voteSymbol('slay')} Gloss</button><button data-vote="nay" data-id="${esc(p.id)}">${voteSymbol('nay')} Toss</button></div>`}<p><button class="text-button" data-detail="${esc(p.id)}">Product details & community results</button></p><a href="#vote">Keep voting →</a></section>`;}
function dismissSharePrompt(){clearTimeout(sharePromptTimer);document.querySelector('#vote-share-prompt')?.remove();}
function showVoteSharePrompt(p){dismissSharePrompt();if(!p?.id)return;const el=document.createElement('aside');el.id='vote-share-prompt';el.setAttribute('aria-label','Share your last vote');el.innerHTML=`<span role="status">You ${p.my_vote==='slay'?'Glossed':'Tossed'} ${esc(p.name)}</span><button data-share-last="${esc(p.id)}">Share?</button><button data-dismiss-share aria-label="Dismiss share prompt">×</button>`;document.body.append(el);sharePromptTimer=setTimeout(dismissSharePrompt,7000);}
function clearSharePreview(){shareRequest++;if(currentShare)URL.revokeObjectURL(currentShare.preview);currentShare=null;}
async function shareProduct(p){
 if(state.busy){toast('Your vote is saving. Try Share again in a moment.');return;}
 if(!p)return;dismissSharePrompt();clearSharePreview();const request=shareRequest;
 openModal('<h2 id="modal-title">Create your share card</h2><p role="status">Preparing your branded product image…</p>');
 try{
  const art=await generateShareImage({...p});if(request!==shareRequest||!$('#modal').open)return;
  const preview=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(art.blob);});if(request!==shareRequest||!$('#modal').open)return;currentShare={...art,preview};const share=currentShare;
  openModal(`<h2 id="modal-title">${art.model.choice?'Share your vote':'Ask your friends'}</h2><img class="share-preview" src="${share.preview}" alt="Branded share image for ${esc(art.model.name)}"><p class="form-note">${art.photoAvailable?'1080 × 1920 · Ready for stories and messages.':'No product photo yet. Your branded card is ready to share.'}</p><div class="share-options">${canShareImage(art)?'<button class="pink" data-share-native>Share image</button>':''}<a class="profile-link" href="${share.preview}" download="${esc(art.file.name)}">Download image</a><button data-share-copy>Copy product link</button></div><p id="share-status" role="status"></p><label class="share-link-label">Product link<input readonly value="${esc(art.model.url)}"></label>`);
  if(canShareImage(art)&&navigator.userActivation?.isActive){try{await navigator.share(nativeShareData(art));}catch(e){if(e.name!=='AbortError')$('#share-status').textContent='Your image is ready. Tap Share image to open your phone’s share menu.';}}
 }catch(e){if(request===shareRequest&&$('#modal').open)openModal(`<h2 id="modal-title">Couldn’t create the image</h2><p>${esc(e.message)}</p><p>You can still share the product link:</p><input readonly value="${esc(productShareUrl(p.id))}"><button data-share="${esc(p.id)}">Try again</button>`);}
}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.hasAttribute('data-dismiss-share')){dismissSharePrompt();return;}
 if(b.dataset.share||b.dataset.shareLast){const id=b.dataset.share||b.dataset.shareLast;const p=product(id)||(state.lastVote?.id===id?state.lastVote:null);await shareProduct(p);return;}
 if(b.hasAttribute('data-share-native')&&currentShare){const art=currentShare;b.disabled=true;try{await navigator.share(nativeShareData(art));}catch(err){if(err.name!=='AbortError'&&$('#share-status'))$('#share-status').textContent='Sharing isn’t available here. Download the image and copy the link instead.';}finally{b.disabled=false;}return;}
 if(b.hasAttribute('data-share-copy')&&currentShare){try{await navigator.clipboard.writeText(currentShare.model.url);$('#share-status').textContent='Product link copied.';}catch{$('#share-status').textContent='Select and copy the product link below.';}return;}
});
$('#modal').addEventListener('close',clearSharePreview);
document.addEventListener('pointerdown',e=>{if(e.target.closest('#vote-card'))dismissSharePrompt();});
window.addEventListener('hashchange',()=>{dismissSharePrompt();if(currentShare){$('#modal').close();clearSharePreview();}});

function photoPlaceholder(p){return `<div class="photo-invite"><svg viewBox="0 0 48 48" width="48" height="48" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 13h9l3-5h8l3 5h9v27H8z"/><circle cx="24" cy="26" r="8"/><path d="M35 18h1"/></svg><strong>Have this product?</strong><span>Help the community see it.</span><a href="#submit-photo/${encodeURIComponent(p.id)}">Share your photo ↗</a></div>`;}
function communityProductFields(){return fields().replace(/<label>Product photo[\s\S]*?<\/label>/,'');}
function communityPhotoFields(required){return `<label>Your own product photo${required?'':' · optional'}<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" ${required?'required':''} data-community-photo></label><p class="form-note">JPEG, PNG, or WebP · up to 15 MB. Photograph the actual product. Please do not upload screenshots or photos downloaded from another website.</p><div class="community-photo-preview"></div><label class="photo-consent"><input name="photo_consent" type="checkbox" ${required?'required':''}><span>${esc(PHOTO_CONSENT)}</span></label><p class="form-note">We review photos before publishing. Photos do not influence votes or scores.</p>`;}
function photoSubmissionPage(id){
 const p=product(id);
 if(id&&!p)return '<h1>Product unavailable</h1><p>This product may have been hidden or removed.</p><a href="#discover">Explore products →</a>';
 return `<div class="eyebrow">Real products. Community photos.</div><h1>Share your <em>photo.</em></h1><p>Help someone recognize a product they have tried. Your photo will be reviewed before it appears.</p><section class="panel">${state.user?`<form id="photo-submission-form"><p>Submitting from ${esc(accountLabel())}</p><label>Product<select name="product_id" required><option value="">Choose a product</option>${[...state.products].sort((a,b)=>(a.brand+a.name).localeCompare(b.brand+b.name)).map(item=>`<option value="${esc(item.id)}" ${item.id===id?'selected':''}>${esc(item.brand+' · '+item.name)}</option>`).join('')}</select></label><label>I’m submitting as<select name="submitter_type"><option value="tech">A nail tech / community member</option><option value="brand">A brand / company representative</option></select></label>${communityPhotoFields(true)}<label>Notes · optional<textarea name="description" maxlength="1500" placeholder="Anything we should know about your photo?"></textarea></label><p class="form-error" role="alert"></p><button type="submit" class="pink wide">Send photo for review</button></form>`:`${p?`<h2>${esc(p.brand)} · ${esc(p.name)}</h2>`:''}<p>Sign in with your free account to submit a photo.</p><button class="pink" data-action="signin">Sign in or sign up</button>`}</section>`;
}
async function submitCommunityPhoto(form,data){
 const file=form.elements.photo?.files[0];
 if(file&&!form.elements.photo_consent.checked)throw new Error('Please read and agree to the photo permission.');
 const {photo,photo_consent,...values}=data;
 const base64=file?await resizePhoto(file):undefined;
 await api('/submissions',{...values,base64,original_filename:file?.name,photo_consent:!!file&&form.elements.photo_consent.checked,consent_version:PHOTO_CONSENT_VERSION});
}
document.addEventListener('change',async e=>{
 if(!e.target.matches('[data-community-photo]'))return;
 const input=e.target,form=input.form,preview=form.querySelector('.community-photo-preview'),file=input.files[0];
 preview.textContent='';form.elements.photo_consent.checked=false;
 form.elements.photo_consent.required=!!file;
 if(!file)return;
 try{const base64=await resizePhoto(file);if(input.files[0]!==file||!form.isConnected)return;preview.innerHTML=`<img src="data:image/webp;base64,${base64}" alt="Your selected product photo">`;}
 catch(err){input.value='';preview.textContent=err.message;}
});

let photoBatch=[],photoBatchBusy=false;
function photoDesk(){
 photoBatch=[];
 openModal(`<h2 id="modal-title">Your photo desk</h2><p>Download your product list, then name photos using the suggested filenames. Keep the product ID at the start. You can also select the matching product below without renaming files.</p><button data-action="photo-list">Download photo naming list</button><p class="form-note">Keep the real file extension (.jpg, .png, or .webp). Renaming a file does not convert it. Upload your own photos or photos with permission covering your intended uses.</p><label>Choose up to 100 photos<input id="photo-batch" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><p id="photo-batch-status" role="status"></p><div id="photo-batch-rows"></div><button class="pink wide" data-action="photo-batch-save" hidden>Save selected photos</button>`);
}
function downloadPhotoList(){
 const cell=value=>'"'+String(value).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';
 const list=[['product_id','brand','product_name','category','suggested_filename','has_photo'],...(state.admin?.products||[]).map(p=>[p.id,p.brand,p.name,p.category,photoFilename(p),p.image?'yes':'no'])];
 const csv='\ufeff'+list.map(row=>row.map(cell).join(',')).join('\r\n');
 const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);a.download='gloss-or-toss-photo-naming-list.csv';a.click();
}
document.addEventListener('change',e=>{
 if(e.target.id!=='photo-batch'||photoBatchBusy)return;
 const files=[...e.target.files];
 if(files.length>100){$('#photo-batch-status').textContent='Choose up to 100 photos at a time.';e.target.value='';return;}
 photoBatch=files.map(file=>({file,product:matchPhotoFilename(file.name,state.admin.products),saved:false}));
 const sorted=[...state.admin.products].sort((a,b)=>(a.brand+a.name).localeCompare(b.brand+b.name));
 $('#photo-batch-rows').innerHTML=photoBatch.map((item,i)=>`<div class="panel" data-photo-row="${i}"><label><input type="checkbox" data-photo-selected checked> ${esc(item.file.name)}</label><label>Match product<select data-photo-match><option value="">Choose a product</option>${sorted.map(p=>`<option value="${esc(p.id)}" ${p.id===item.product?.id?'selected':''}>${esc(p.brand+' · '+p.name)}${p.image?' (replaces photo)':''}</option>`).join('')}</select></label><button type="button" data-photo-preview="${i}">Preview photo</button><div data-photo-preview-box></div><p data-photo-result role="status">${item.product?'Matched by product ID.':'Choose the product for this photo.'}</p></div>`).join('');
 $('[data-action="photo-batch-save"]').hidden=!files.length;
 $('#photo-batch-status').textContent=files.length+' photos ready to review. Nothing is saved yet.';
});
async function savePhotoBatch(){
 if(photoBatchBusy)return;
 photoBatchBusy=true;
 const button=$('[data-action="photo-batch-save"]');button.disabled=true;
 const selected=[...document.querySelectorAll('[data-photo-row]')].filter(r=>r.querySelector('[data-photo-selected]').checked&&!photoBatch[Number(r.dataset.photoRow)].saved);
 const used=new Set();let saved=0;
 try{
  for(const row of selected){
   const item=photoBatch[Number(row.dataset.photoRow)],id=row.querySelector('[data-photo-match]').value,result=row.querySelector('[data-photo-result]');
   if(!id){result.textContent='Choose a product first.';continue;}
   if(used.has(id)){result.textContent='Another selected photo already targets this product. Select one photo per product.';continue;}used.add(id);
   row.querySelectorAll('input,select,button').forEach(n=>n.disabled=true);
   try{result.textContent='Uploading…';const base64=await resizePhoto(item.file);const uploaded=await api('/admin/upload',{base64});await api('/admin/product-photo',{id,image:uploaded.image});item.saved=true;saved++;result.textContent='Saved ✓';}
   catch(err){result.textContent=err.message;row.querySelectorAll('input,select,button').forEach(n=>n.disabled=false);}
  }
  state.admin=await api('/admin/data');await refresh();await render();
  $('#photo-batch-status').textContent=`Saved ${saved} of ${selected.length} selected photos. Fix any remaining rows and retry; saved photos are skipped.`;
 }catch(err){$('#photo-batch-status').textContent=err.message;}
 finally{photoBatchBusy=false;button.disabled=false;}
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('button');if(!button)return;
 if(button.dataset.action==='photo-desk'&&!photoBatchBusy)photoDesk();
 if(button.dataset.action==='photo-list')downloadPhotoList();
 if(button.dataset.action==='photo-batch-save')await savePhotoBatch();
 if(button.hasAttribute('data-photo-preview')){const row=button.closest('[data-photo-row]'),box=row.querySelector('[data-photo-preview-box]');try{const encoded=await resizePhoto(photoBatch[Number(button.dataset.photoPreview)].file);box.innerHTML=`<img class="submission-review-photo" src="data:image/webp;base64,${encoded}" alt="Selected photo preview">`;}catch(err){box.textContent=err.message;}}
});
document.addEventListener('click',e=>{if(photoBatchBusy&&e.target.closest('[data-action="close"]')){e.preventDefault();e.stopImmediatePropagation();}},true);
$('#modal').addEventListener('cancel',e=>{if(photoBatchBusy)e.preventDefault();});

await startAuthentication();
